// 0208: generated bytes never start with an implicit empty input list. A trusted executor supplies an
// exhaustive artifact-input inventory; all knowledge packages are read independently from SQL.
import { randomUUID } from 'node:crypto';
import {
  artifactAclCatalog,
  artifactLineage,
  artifactLineageInputs,
  artifactLineagePackages,
  artifactLineageRecords,
  artifactLineageSources,
  structuredRecordCatalog,
  artifacts,
  blobLifecycle,
  knowledgeEvidenceItems,
  knowledgeEvidencePackages,
  knowledgeSources,
  memberships,
  tombstones,
  withTenantTx,
  workArtifacts,
  workAssignments,
  type AppDatabase,
  type TenantContext,
  type Tx,
} from '@ensemus/database';
import { createServiceContext } from '@ensemus/database/service';
import { strongestClass } from '@ensemus/domain/knowledge';
import { canChangeContent, MAX_FILE_BYTES, type WorkState } from '@ensemus/domain/work-unit';
import type { Classification } from '@ensemus/domain/policy';
import { TOMBSTONE_RECORDED } from '@ensemus/domain/tombstone-ledger';
import { and, asc, eq, inArray, sql, type SQL } from 'drizzle-orm';
import { objectKey, type ObjectStore } from '../artifacts';
import { AppError, pgCode } from '../errors';
import { emit } from '../events';
import { idSchema } from '../ids';
import { idFromRequest } from '../request-id';
import { closeOutdatedReviews, loadChangeable, loadReadable } from '../work';
import { verificationHash } from './verification-proof';
import type { DerivedArtifactPurge } from './ports';
