export type { DerivedArtifactPurge } from './ports';

export type ArtifactExecution =
  { kind: 'agent_run'; id: string } | { kind: 'system'; id: string; template: string };
export type GeneratedArtifactWrite = {
  artifactId: string;
  workUnitId: string;
  writeId: string;
  generation: number;
  artifactSha256: string;
  classification: Classification;
};
export type StructuredArtifactInput = {
  kind: 'work_unit' | 'project' | 'client';
  id: string;
  sha256: string;
};
export interface ArtifactInputInventory {
  /** Must validate the actual run/template/executor, current writer authority and every artifact read
   * across prior turns/tools. An unavailable/exhaustiveness-unknown inventory returns known:false.
   * Inspection must use nonlocking metadata reads: this module locks input sources before work/run
   * parents. For a system template, noKnowledge is an explicit assertion about the exact output hash, never
   * inferred from a missing package list. M4 implements this after the joined compiler/tool ledger. */
  inspectInTx(
    tx: Tx,
    context: TenantContext,
    input: {
      execution: ArtifactExecution;
      workUnitId: string;
      artifactSha256: string;
    },
  ): Promise<
    | { known: false }
    | {
        known: true;
        execution: ArtifactExecution;
        workUnitId: string;
        viewerMembershipId: string | null;
        classification: Classification;
        noKnowledge: boolean;
        artifactInputs: readonly { artifactId: string; sha256: string }[];
        /** Exhaustive trusted structured read ledger, including target Work and any actual parent
         * records read. Historical mutable-record hashes remain provenance, not a live equality gate. */
        recordInputs: readonly StructuredArtifactInput[];
      }
  >;
}
export interface GeneratedArtifactProvenance {
  /** Before noteDraftUpload/blob_lifecycle INSERT and before any ObjectStore.put. */
  beginInTx(
    tx: Tx,
    context: TenantContext,
    input: {
      execution: ArtifactExecution;
      artifactId: string;
      workUnitId: string;
      artifactSha256: string;
      sizeBytes: number;
    },
  ): Promise<{ alreadyPublished: boolean; write: GeneratedArtifactWrite }>;
  /** Only after put fulfilled, in the same transaction as the artifact+work link INSERTs. */
  publishInTx(tx: Tx, context: TenantContext, write: GeneratedArtifactWrite): Promise<void>;
}
export interface DerivedArtifactLifecycle {
  /** Must honor legal holds, durably tombstone/remove the artifact row, prove all old puts quiescent,
   * and erase bytes. A timeout, absent HEAD or elapsed lease does not prove writer quiescence. */
  erase(
    context: TenantContext,
    input: {
      artifactId: string;
      workUnitId: string | null;
      objectKey: string;
      artifactSha256: string;
      writeId: string;
      generation: number;
      writeState: 'active' | 'settled' | 'fenced' | 'unknown';
    },
  ): Promise<{ state: 'purged'; quiescent: true } | { state: 'held' | 'unconfirmed' }>;
}
export type ArtifactProvenanceDeps = { inventory: ArtifactInputInventory };
export type DerivedArtifactPurgeDeps = {
  database: AppDatabase;
  store: ObjectStore;
  lifecycle?: DerivedArtifactLifecycle;
};
/** Record closure is distinct from one viewer losing access. Only a durably deleted/tombstoned
 * record can authorize destruction of every derived file; revocation alone closes fresh serving. */
export interface StructuredRecordPurge extends DerivedArtifactPurge {
  purgeRecord(
    context: TenantContext,
    input: { kind: StructuredArtifactInput['kind']; id: string; limit: number },
  ): ReturnType<DerivedArtifactPurge['purgeSource']>;
  confirmRecordInTx(
    tx: Tx,
    context: TenantContext,
    input: { kind: StructuredArtifactInput['kind']; id: string },
  ): Promise<{ remaining: number }>;
}

const MAX_INPUTS = 1000;
const checkedId = (value: string) => {
  const parsed = idSchema.safeParse(value);
  if (!parsed.success) throw new AppError('INVALID_INPUT');
  return parsed.data;
};
const checkedHash = (value: string) => {
  if (typeof value !== 'string' || !/^[0-9a-f]{64}$/.test(value))
    throw new AppError('INVALID_INPUT');
  return value;
};
/** No missing-list => empty conversion. A mutable record can have multiple actual historical reads. */
export function normalizeStructuredInputs(
  raw: unknown,
  targetWorkId: string,
): readonly StructuredArtifactInput[] {
  const target = checkedId(targetWorkId);
  if (!Array.isArray(raw) || !raw.length || raw.length > MAX_INPUTS)
    throw new AppError('INVALID_STATE');
  const records = new Map<string, StructuredArtifactInput>();
  for (const value of raw) {
    if (
      !value ||
      typeof value !== 'object' ||
      !['work_unit', 'project', 'client'].includes(value.kind)
    )
      throw new AppError('INVALID_INPUT');
    const row: StructuredArtifactInput = {
      kind: value.kind,
      id: checkedId(value.id),
      sha256: checkedHash(value.sha256),
    };
    records.set(`${row.kind}:${row.id}:${row.sha256}`, row);
  }
  if (![...records.values()].some((row) => row.kind === 'work_unit' && row.id === target))
    throw new AppError('INVALID_STATE');
  return [...records.values()].sort((a, b) =>
    `${a.kind}:${a.id}:${a.sha256}`.localeCompare(`${b.kind}:${b.id}:${b.sha256}`),
  );
}
type StructuredSnapshot = StructuredArtifactInput & { classification: Classification };
const recordKey = (record: { kind: string; id: string }) => `${record.kind}:${record.id}`;
async function noLockWait<T>(operation: Promise<T>): Promise<T> {
  try {
    return await operation;
  } catch (error) {
    if (pgCode(error) === '55P03') throw new AppError('VERSION_CONFLICT');
    throw error;
  }
}
async function structuredInventory(
  tx: Tx,
  context: TenantContext,
  direct: readonly StructuredArtifactInput[],
  inputIds: readonly string[],
  viewer: string | null,
  system: boolean,
  workUnitId: string,
): Promise<readonly StructuredSnapshot[]> {
  const records = new Map<
    string,
    StructuredArtifactInput & { classification: Classification | null }
  >();
  const add = (record: StructuredArtifactInput, classification: Classification | null) => {
    const key = `${recordKey(record)}:${record.sha256}`,
      existing = records.get(key);
    const classes = [
      ...(classification ? [classification] : []),
      ...(existing?.classification ? [existing.classification] : []),
    ];
    records.set(key, {
      ...record,
      classification: classes.length ? strongestClass(classes) : null,
    });
    if (records.size > MAX_INPUTS) throw new AppError('INVALID_INPUT');
  };
  // Direct read classes are resolved from current metadata below; inherited classes remain pinned.
  for (const record of direct) add(record, null);
  if (inputIds.length) {
    const inherited = await tx
      .selectDistinct({
        recordKind: artifactLineageRecords.recordKind,
        recordId: artifactLineageRecords.recordId,
        recordSha256: artifactLineageRecords.recordSha256,
        classification: artifactLineageRecords.classification,
      })
      .from(artifactLineageRecords)
      .where(inArray(artifactLineageRecords.artifactId, [...inputIds]))
      .limit(MAX_INPUTS + 1);
    if (inherited.length > MAX_INPUTS) throw new AppError('INVALID_INPUT');
    for (const row of inherited)
      add(
        {
          kind: row.recordKind as StructuredArtifactInput['kind'],
          id: row.recordId,
          sha256: row.recordSha256,
        },
        row.classification as Classification,
      );
  }
  if (
    system &&
    [...records.values()].some((row) => row.kind !== 'work_unit' || row.id !== workUnitId)
  )
    throw new AppError('INVALID_STATE');
  const unique = [
    ...new Map([...records.values()].map((record) => [recordKey(record), record])).values(),
  ];
  const metadata = await tx
    .select()
    .from(structuredRecordCatalog)
    .where(
      sql`(${structuredRecordCatalog.recordKind},${structuredRecordCatalog.recordId}) in (${sql.join(
        unique.map((row) => sql`(${row.kind},${row.id}::uuid)`),
        sql`,`,
      )})`,
    );
  if (metadata.length !== unique.length || metadata.some((row) => !row.alive))
    throw new AppError('NOT_FOUND');
  // Catalog locks protect authority/class changes without granting UPDATE on record bodies. Project
  // parent locks are authorization metadata only, never invented content reads or hash entries.
  const locks = new Map<string, { kind: StructuredArtifactInput['kind']; id: string }>(
    unique.map((row) => [recordKey(row), { kind: row.kind, id: row.id }]),
  );
  for (const row of metadata)
    if (row.recordKind === 'project' && row.parentRecordId)
      locks.set(`client:${row.parentRecordId}`, { kind: 'client', id: row.parentRecordId });
  for (const lock of [...locks.values()].sort((a, b) => recordKey(a).localeCompare(recordKey(b)))) {
    const result = await tx.execute<{ locked: boolean }>(
      sql`select knowledge.lock_structured_record(${lock.kind},${lock.id}::uuid) as locked`,
    );
    if (!result.rows[0]?.locked) throw new AppError('NOT_FOUND');
  }
  // Re-read after locks: reparenting may have introduced a previously unknown class dependency.
  const current = await tx
    .select()
    .from(structuredRecordCatalog)
    .where(
      sql`(${structuredRecordCatalog.recordKind},${structuredRecordCatalog.recordId}) in (${sql.join(
        unique.map((row) => sql`(${row.kind},${row.id}::uuid)`),
        sql`,`,
      )})`,
    );
  if (
    current.length !== unique.length ||
    current.some(
      (row) =>
        !row.alive ||
        (row.recordKind === 'project' &&
          row.parentRecordId &&
          !locks.has(`client:${row.parentRecordId}`)),
    )
  )
    throw new AppError('VERSION_CONFLICT');
  for (const record of unique) {
    const result = await tx.execute<{ classification: Classification | null; allowed: boolean }>(
      sql`select knowledge.structured_record_class(${record.kind},${record.id}::uuid) as classification,knowledge.structured_record_readable(${record.kind},${record.id}::uuid,${viewer}::uuid) as allowed`,
    );
    const fact = result.rows[0];
    if (!fact?.classification || (!system && !fact.allowed)) throw new AppError('NOT_FOUND');
    for (const historical of [...records.values()].filter(
      (row) => row.kind === record.kind && row.id === record.id,
    ))
      add(historical, fact.classification);
  }
  return [...records.values()]
    .map((row): StructuredSnapshot => {
      if (!row.classification) throw new AppError('INVALID_STATE');
      return { ...row, classification: row.classification };
    })
    .sort((a, b) => `${recordKey(a)}:${a.sha256}`.localeCompare(`${recordKey(b)}:${b.sha256}`));
}
const executionKey = (value: ArtifactExecution) =>
  value.kind === 'agent_run'
    ? `agent_run:${checkedId(value.id)}`
    : `system:${checkedId(value.id)}:${value.template}`;
const requireWorker = (context: TenantContext) => {
  if (context.actorType === 'user') throw new AppError('FORBIDDEN');
};
type Header = typeof artifactLineage.$inferSelect;
type InventoryInput = {
  execution: ArtifactExecution;
  artifactId: string;
  workUnitId: string;
  artifactSha256: string;
  sizeBytes: number;
};

export async function lockArtifactInputSources(
  tx: Tx,
  context: TenantContext,
  input: { artifactId: string; additionalSourceIds?: readonly string[] },
) {
  const artifactId = checkedId(input.artifactId);
  const result = await tx.execute<{ id: string }>(
    sql`select knowledge.artifact_required_sources(${artifactId}::uuid) as id`,
  );
  const ids = [
    ...new Set([
      ...result.rows.map((row) => row.id),
      ...(input.additionalSourceIds ?? []).map(checkedId),
    ]),
  ].sort();
  if (ids.length)
    await tx
      .select({ id: knowledgeSources.id })
      .from(knowledgeSources)
      .where(
        and(
          eq(knowledgeSources.organizationId, context.organizationId),
          inArray(knowledgeSources.id, ids),
        ),
      )
      .orderBy(asc(knowledgeSources.id))
      .for('share');
  await assertStableArtifactSources(tx, context, { artifactId }, new Set(ids));
  return new Set(ids);
}
/** Recheck after obtaining the caller's work/artifact locks; never acquire an unknown source there. */
export async function assertStableArtifactSources(
  tx: Tx,
  _context: TenantContext,
  input: { artifactId: string },
  locked: ReadonlySet<string>,
) {
  const result = await tx.execute<{ id: string }>(
    sql`select knowledge.artifact_required_sources(${checkedId(input.artifactId)}::uuid) as id`,
  );
  if (result.rows.some((row) => !locked.has(row.id))) throw new AppError('VERSION_CONFLICT');
}

async function currentInventory(
  tx: Tx,
  context: TenantContext,
  deps: ArtifactProvenanceDeps,
  input: InventoryInput,
) {
  requireWorker(context);
  const artifactId = checkedId(input.artifactId),
    workUnitId = checkedId(input.workUnitId),
    artifactSha256 = checkedHash(input.artifactSha256);
  if (!Number.isSafeInteger(input.sizeBytes) || input.sizeBytes < 1)
    throw new AppError('INVALID_INPUT');
  const proof = await deps.inventory.inspectInTx(tx, context, {
    execution: input.execution,
    workUnitId,
    artifactSha256,
  });
  if (
    !proof.known ||
    executionKey(proof.execution) !== executionKey(input.execution) ||
    proof.workUnitId !== workUnitId
  )
    throw new AppError('INVALID_STATE');
  const directRecords = normalizeStructuredInputs(proof.recordInputs, workUnitId);
  await loadReadable(tx, context, workUnitId);
  const viewer = proof.viewerMembershipId === null ? null : checkedId(proof.viewerMembershipId);
  if (input.execution.kind === 'agent_run') {
    if (
      !viewer ||
      proof.noKnowledge ||
      (context.actorType !== 'service' && context.membershipId !== viewer)
    )
      throw new AppError('FORBIDDEN');
  } else if (
    context.actorType !== 'service' ||
    !proof.noKnowledge ||
    viewer !== null ||
    proof.artifactInputs.length ||
    !/^[a-z][a-z0-9_./-]{0,79}$/.test(input.execution.template)
  )
    throw new AppError('FORBIDDEN');
  if (proof.artifactInputs.length > MAX_INPUTS) throw new AppError('INVALID_INPUT');
  const inputs = new Map<string, string>();
  const add = (raw: string, hash: string) => {
    const id = checkedId(raw),
      sha = checkedHash(hash);
    if (id === artifactId || (inputs.has(id) && inputs.get(id) !== sha))
      throw new AppError('INVALID_STATE');
    inputs.set(id, sha);
    if (inputs.size > MAX_INPUTS) throw new AppError('INVALID_INPUT');
  };
  proof.artifactInputs.forEach((value) => add(value.artifactId, value.sha256));
  for (let previous = -1; previous !== inputs.size;) {
    previous = inputs.size;
    if (!previous) break;
    const ancestors = await tx
      .select()
      .from(artifactLineageInputs)
      .where(inArray(artifactLineageInputs.artifactId, [...inputs.keys()]));
    ancestors.forEach((value) => add(value.inputArtifactId, value.inputSha256));
  }
  const inputIds = [...inputs.keys()].sort();
  const inputRows = inputIds.length
    ? await tx
        .select()
        .from(artifactAclCatalog)
        .where(inArray(artifactAclCatalog.artifactId, inputIds))
    : [];
  if (inputRows.length !== inputIds.length) throw new AppError('NOT_FOUND');
  for (const row of inputRows) {
    const access = await tx.execute<{ allowed: boolean }>(
      sql`select knowledge.artifact_readable(${row.artifactId}::uuid,${viewer}::uuid) as allowed`,
    );
    if (!row.alive || row.sha256 !== inputs.get(row.artifactId) || !access.rows[0]?.allowed)
      throw new AppError('NOT_FOUND');
  }
  const packages =
    input.execution.kind === 'agent_run'
      ? await tx
          .select()
          .from(knowledgeEvidencePackages)
          .where(eq(knowledgeEvidencePackages.runId, checkedId(input.execution.id)))
          .orderBy(asc(knowledgeEvidencePackages.id))
          .limit(MAX_INPUTS + 1)
      : [];
  if (
    packages.length > MAX_INPUTS ||
    packages.some((value) => value.viewerMembershipId !== viewer || value.workUnitId !== workUnitId)
  )
    throw new AppError('INVALID_STATE');
  const inherited = inputIds.length
    ? await tx
        .select()
        .from(artifactLineagePackages)
        .where(inArray(artifactLineagePackages.artifactId, inputIds))
    : [];
  const packageIds = [
    ...new Set([
      ...packages.map((value) => value.id),
      ...inherited.map((value) => value.packageId),
    ]),
  ].sort();
  if (packageIds.length > MAX_INPUTS) throw new AppError('INVALID_INPUT');
  const packageRows = packageIds.length
    ? await tx
        .select()
        .from(knowledgeEvidencePackages)
        .where(inArray(knowledgeEvidencePackages.id, packageIds))
        .orderBy(asc(knowledgeEvidencePackages.id))
    : [];
  if (packageRows.length !== packageIds.length) throw new AppError('INVALID_STATE');
  const sourceIds = new Set<string>();
  if (packageIds.length) {
    const items = await tx
      .select({ id: knowledgeEvidenceItems.sourceId })
      .from(knowledgeEvidenceItems)
      .where(inArray(knowledgeEvidenceItems.packageId, packageIds));
    items.forEach((value) => sourceIds.add(value.id));
  }
  if (inputIds.length) {
    const inheritedSources = await tx.execute<{
      id: string;
    }>(sql`select distinct knowledge.artifact_required_sources(v.id) as id
      from (values ${sql.join(
        inputIds.map((value) => sql`(${value}::uuid)`),
        sql`,`,
      )}) v(id)`);
    inheritedSources.rows.forEach((value) => sourceIds.add(value.id));
  }
  if (sourceIds.size > MAX_INPUTS) throw new AppError('INVALID_INPUT');
  const sources = sourceIds.size
    ? await tx
        .select({
          id: knowledgeSources.id,
          classification: knowledgeSources.classification,
          state: knowledgeSources.state,
        })
        .from(knowledgeSources)
        .where(inArray(knowledgeSources.id, [...sourceIds]))
        .orderBy(asc(knowledgeSources.id))
        .for('share')
    : [];
  if (sources.length !== sourceIds.size || sources.some((value) => value.state !== 'active'))
    throw new AppError('KNOWLEDGE_SOURCE_CLOSED');
  if (sourceIds.size) {
    const allowed = await tx.execute<{
      id: string;
    }>(sql`select s.id from knowledge.sources s where s.organization_id=${context.organizationId}::uuid
      and s.id in (${sql.join(
        [...sourceIds].map((value) => sql`${value}::uuid`),
        sql`,`,
      )})
      and s.id in(select knowledge.readable_source_ids(${viewer}::uuid))
      and not exists(select 1 from platform.tombstones t where t.organization_id=s.organization_id and t.target_type='knowledge_source' and t.target_id=s.id)`);
    if (allowed.rows.length !== sourceIds.size) throw new AppError('KNOWLEDGE_SOURCE_CLOSED');
  }
  // Source locks come first. Obtain the target Work lock without waiting before taking any
  // structured metadata lock, so body-writer -> catalog ordering cannot turn into a wait cycle.
  await noLockWait(
    tx.execute(
      sql`select id from work.work_units where organization_id=${context.organizationId}::uuid and id=${workUnitId}::uuid for update nowait`,
    ),
  );
  const work = await loadReadable(tx, context, workUnitId);
  for (const inputId of inputIds)
    await assertStableArtifactSources(tx, context, { artifactId: inputId }, sourceIds);
  if (input.execution.kind === 'agent_run') {
    if (!viewer) throw new AppError('FORBIDDEN');
    const [member] = await noLockWait(
      tx
        .select()
        .from(memberships)
        .where(and(eq(memberships.id, viewer), eq(memberships.status, 'active')))
        .for('share', { noWait: true }),
    );
    const [assigned] = await tx
      .select({ id: workAssignments.membershipId })
      .from(workAssignments)
      .where(
        and(eq(workAssignments.workUnitId, workUnitId), eq(workAssignments.membershipId, viewer)),
      );
    const access = await tx.execute<{ allowed: boolean }>(
      sql`select knowledge.can_read_work(${workUnitId}::uuid,${viewer}::uuid) as allowed`,
    );
    if (
      !member ||
      !access.rows[0]?.allowed ||
      (!['owner', 'admin'].includes(member.role) && work.ownerMembershipId !== viewer && !assigned)
    )
      throw new AppError('FORBIDDEN');
  }
  const records = await noLockWait(
    structuredInventory(
      tx,
      context,
      directRecords,
      inputIds,
      viewer,
      input.execution.kind === 'system',
      workUnitId,
    ),
  );
  const classification = strongestClass([
    work.classification as Classification,
    proof.classification,
    ...packageRows.map((value) => value.strongestClassification as Classification),
    ...inputRows.map((value) => value.classification as Classification),
    ...sources.map((value) => value.classification as Classification),
    ...records.map((value) => value.classification),
  ]);
  const inventorySha256 = verificationHash(
    JSON.stringify([
      executionKey(input.execution),
      workUnitId,
      viewer,
      classification,
      packageRows.map((value) => [value.id, value.packageSha256]),
      inputIds.map((value) => [value, inputs.get(value)]),
      [...sourceIds].sort(),
      records.map((value) => [value.kind, value.id, value.sha256]),
    ]),
  );
  return {
    artifactId,
    work,
    viewer,
    classification,
    inventorySha256,
    packageIds,
    sourceIds: [...sourceIds].sort(),
    inputs: inputIds.map((id) => ({ artifactId: id, sha256: inputs.get(id)! })),
    records,
  };
}

export function createArtifactProvenance(
  deps: ArtifactProvenanceDeps,
): GeneratedArtifactProvenance {
  return {
    async beginInTx(tx, context, input) {
      const inventory = await currentInventory(tx, context, deps, input);
      const [previous] = await tx
        .select()
        .from(artifactLineage)
        .where(eq(artifactLineage.artifactId, inventory.artifactId))
        .for('update');
      if (previous) {
        const [catalog] = await tx
          .select()
          .from(artifactAclCatalog)
          .where(eq(artifactAclCatalog.artifactId, inventory.artifactId));
        if (
          previous.state !== 'bound' ||
          !previous.structuredInventoryComplete ||
          previous.writeState !== 'settled' ||
          previous.physicalPurgedAt ||
          !catalog?.alive ||
          previous.inventorySha256 !== inventory.inventorySha256 ||
          previous.artifactSha256 !== input.artifactSha256
        )
          throw new AppError('INVALID_STATE');
        return {
          alreadyPublished: true,
          write: {
            artifactId: previous.artifactId,
            workUnitId: inventory.work.id,
            writeId: previous.writeId,
            generation: previous.generation,
            artifactSha256: previous.artifactSha256,
            classification: previous.classification as Classification,
          },
        };
      }
      const [catalog] = await tx
        .select({ id: artifactAclCatalog.artifactId })
        .from(artifactAclCatalog)
        .where(eq(artifactAclCatalog.artifactId, inventory.artifactId));
      if (catalog) throw new AppError('INVALID_STATE');
      const write: GeneratedArtifactWrite = {
        artifactId: inventory.artifactId,
        workUnitId: inventory.work.id,
        writeId: randomUUID(),
        generation: 1,
        artifactSha256: input.artifactSha256,
        classification: inventory.classification,
      };
      await tx.insert(artifactLineage).values({
        organizationId: context.organizationId,
        artifactId: write.artifactId,
        workUnitId: write.workUnitId,
        objectKey: objectKey(context.organizationId, write.artifactId),
        artifactSha256: write.artifactSha256,
        sizeBytes: input.sizeBytes,
        classification: write.classification,
        executionKind: input.execution.kind,
        executionId: checkedId(input.execution.id),
        executorRef: input.execution.kind === 'system' ? input.execution.template : 'agent-run/v1',
        viewerMembershipId: inventory.viewer,
        inventorySha256: inventory.inventorySha256,
        inventoryComplete: true,
        structuredInventoryComplete: true,
        state: 'pending',
        writeId: write.writeId,
        generation: 1,
        writeState: 'active',
      });
      if (inventory.inputs.length)
        await tx.insert(artifactLineageInputs).values(
          inventory.inputs.map((value) => ({
            organizationId: context.organizationId,
            artifactId: write.artifactId,
            inputArtifactId: value.artifactId,
            inputSha256: value.sha256,
          })),
        );
      if (inventory.packageIds.length)
        await tx.insert(artifactLineagePackages).values(
          inventory.packageIds.map((packageId) => ({
            organizationId: context.organizationId,
            artifactId: write.artifactId,
            packageId,
          })),
        );
      if (inventory.sourceIds.length)
        await tx.insert(artifactLineageSources).values(
          inventory.sourceIds.map((sourceId) => ({
            organizationId: context.organizationId,
            artifactId: write.artifactId,
            sourceId,
          })),
        );
      await tx.insert(artifactLineageRecords).values(
        inventory.records.map((record) => ({
          organizationId: context.organizationId,
          artifactId: write.artifactId,
          recordKind: record.kind,
          recordId: record.id,
          recordSha256: record.sha256,
          classification: record.classification,
        })),
      );
      if (input.execution.kind === 'agent_run') await registerGeneratedWriter(tx, context, write);
      return { alreadyPublished: false, write };
    },
    async publishInTx(tx, context, write) {
      requireWorker(context);
      const [initial] = await tx
        .select()
        .from(artifactLineage)
        .where(eq(artifactLineage.artifactId, checkedId(write.artifactId)));
      if (
        !initial ||
        !initial.structuredInventoryComplete ||
        !initial.executionId ||
        !initial.workUnitId ||
        !['agent_run', 'system'].includes(initial.executionKind)
      )
        throw new AppError('INVALID_STATE');
      const execution: ArtifactExecution =
        initial.executionKind === 'agent_run'
          ? { kind: 'agent_run', id: initial.executionId }
          : { kind: 'system', id: initial.executionId, template: initial.executorRef };
      const inventory = await currentInventory(tx, context, deps, {
        execution,
        artifactId: initial.artifactId,
        workUnitId: initial.workUnitId,
        artifactSha256: initial.artifactSha256,
        sizeBytes: initial.sizeBytes,
      });
      const [current] = await tx
        .select()
        .from(artifactLineage)
        .where(eq(artifactLineage.artifactId, initial.artifactId))
        .for('update');
      if (
        !current ||
        current.state !== 'pending' ||
        current.writeState !== 'active' ||
        current.writeId !== write.writeId ||
        current.generation !== write.generation ||
        current.artifactSha256 !== write.artifactSha256 ||
        current.inventorySha256 !== inventory.inventorySha256
      )
        throw new AppError('INVALID_STATE');
      const rows = await tx
        .update(artifactLineage)
        .set({ state: 'bound', writeState: 'settled' })
        .where(eq(artifactLineage.artifactId, current.artifactId))
        .returning({ id: artifactLineage.artifactId });
      if (rows.length !== 1) throw new AppError('INVALID_STATE');
    },
  };
}

/** The generated-output sibling of addArtifact. The authoritative inventory port is mandatory;
 * caller-supplied citations, an empty package query and a model's claims cannot stand in for it. */
export async function addGeneratedArtifact(
  database: AppDatabase,
  store: ObjectStore,
  context: TenantContext,
  input: {
    workUnitId: string;
    name: string;
    mimeType: string;
    body: Buffer;
    execution: ArtifactExecution;
    requestKey: string;
  },
  deps: ArtifactProvenanceDeps,
) {
  requireWorker(context);
  const name = input.name.trim().slice(0, 255);
  if (!name || !input.requestKey || !input.body.length) throw new AppError('INVALID_INPUT');
  if (input.body.length > MAX_FILE_BYTES) throw new AppError('FILE_TOO_LARGE');
  const sha256 = verificationHash(input.body);
  const artifactId = idFromRequest('generated-artifact', context.organizationId, input.requestKey, [
    input.workUnitId,
    executionKey(input.execution),
    name,
    sha256,
  ]);
  const provenance = createArtifactProvenance(deps);
  const first = await withTenantTx(database, context, async (tx) => {
    const started = await provenance.beginInTx(tx, context, {
      execution: input.execution,
      artifactId,
      workUnitId: input.workUnitId,
      artifactSha256: sha256,
      sizeBytes: input.body.length,
    });
    const work = await loadChangeable(tx, context, input.workUnitId);
    if (!canChangeContent(work.status as WorkState)) throw new AppError('INVALID_STATE');
    if (!started.alreadyPublished)
      await tx.insert(blobLifecycle).values({
        organizationId: context.organizationId,
        artifactId,
        objectKey: objectKey(context.organizationId, artifactId),
        state: 'uploading',
        purgeAfter: new Date(Date.now() + 3600000),
      });
    return started;
  });
  if (first.alreadyPublished) return { id: artifactId };
  // A rejected put is UNKNOWN: retain the active token, even if HEAD is absent. Only a genuine
  // adapter fence can recover it. A fulfilled put proves this invocation's writer has finished.
  if (input.execution.kind === 'agent_run') await claimGeneratedPut(database, context, first.write);
  await store.put(objectKey(context.organizationId, artifactId), input.body, input.mimeType);
  if (input.execution.kind === 'agent_run')
    await settleGeneratedPut(database, context, first.write);
  try {
    return await withTenantTx(database, context, async (tx) => {
      await provenance.publishInTx(tx, context, first.write);
      const work = await loadChangeable(tx, context, input.workUnitId);
      if (!canChangeContent(work.status as WorkState)) throw new AppError('INVALID_STATE');
      await tx.insert(artifacts).values({
        organizationId: context.organizationId,
        id: artifactId,
        name,
        mimeType: input.mimeType,
        objectKey: objectKey(context.organizationId, artifactId),
        sha256,
        sizeBytes: input.body.length,
        classification: first.write.classification,
        createdByMembershipId: null,
        provenanceState: 'bound',
      });
      await tx
        .insert(workArtifacts)
        .values({ organizationId: context.organizationId, artifactId, workUnitId: work.id });
      await tx.delete(blobLifecycle).where(eq(blobLifecycle.artifactId, artifactId));
      await emit(tx, context, {
        eventType: 'work.artifact_added',
        aggregateType: 'work_unit',
        aggregateId: work.id,
        aggregateVersion: work.version,
        classification: first.write.classification,
        payload: { work_unit_id: work.id, artifact_id: artifactId },
      });
      await closeOutdatedReviews(tx, context, work);
      return { id: artifactId };
    });
  } catch (error) {
    // A lost commit response may already have published. Never destroy that file. Otherwise mark the
    // completed writer settled, durably blocked, and leave physical erasure to the hold-aware adapter.
    await recordFulfilledGeneratedPutFailure(database, context, first.write).catch(() => undefined);
    throw error;
  }
}

/** Trusted writer calls this ONLY after its exact put promise fulfilled and publication failed.
 * Unknown/rejected puts must never call it. A lost published commit is retained, never destroyed. */
export async function recordFulfilledGeneratedPutFailure(
  database: AppDatabase,
  context: TenantContext,
  write: GeneratedArtifactWrite,
) {
  requireWorker(context);
  await withTenantTx(database, createServiceContext(context.organizationId), async (tx) => {
    const [header] = await tx
      .select()
      .from(artifactLineage)
      .where(eq(artifactLineage.artifactId, checkedId(write.artifactId)))
      .for('update');
    if (
      !header ||
      header.writeId !== write.writeId ||
      header.generation !== write.generation ||
      header.artifactSha256 !== write.artifactSha256 ||
      header.state === 'bound'
    )
      return;
    if (
      context.actorType === 'agent' &&
      (header.executionKind !== 'agent_run' ||
        header.executionId !== context.agentRunId ||
        header.viewerMembershipId !== context.membershipId)
    )
      throw new AppError('FORBIDDEN');
    await tx
      .update(artifactLineage)
      .set({ state: 'blocked', writeState: 'settled' })
      .where(eq(artifactLineage.artifactId, header.artifactId));
    await markArtifactTombstone(tx, createServiceContext(context.organizationId), header);
  });
}

async function markArtifactTombstone(
  tx: Tx,
  context: TenantContext,
  header: Header,
  reasonCode: 'KNOWLEDGE_SOURCE_PURGED' | 'STRUCTURED_INPUT_PURGED' = 'KNOWLEDGE_SOURCE_PURGED',
) {
  const inserted = await tx
    .insert(tombstones)
    .values({
      organizationId: context.organizationId,
      targetType: 'artifact',
      targetId: header.artifactId,
      reasonCode,
    })
    .onConflictDoNothing()
    .returning({ id: tombstones.targetId });
  await tx
    .insert(blobLifecycle)
    .values({
      organizationId: context.organizationId,
      artifactId: header.artifactId,
      objectKey: header.objectKey,
      state: 'deleting',
      purgeAfter: new Date(),
    })
    .onConflictDoUpdate({
      target: [blobLifecycle.organizationId, blobLifecycle.artifactId],
      set: { state: 'deleting', purgeAfter: new Date() },
    });
  if (inserted.length)
    await emit(tx, context, {
      eventType: TOMBSTONE_RECORDED,
      aggregateType: 'artifact',
      aggregateId: header.artifactId,
      aggregateVersion: 1,
      classification: header.classification,
      payload: { artifact_id: header.artifactId },
    });
}

/** Lifecycle adapters can use this after positive writer quiescence and an atomic legal-hold check.
 * Normal service SELECT still cannot see blocked file contents. The narrow SQL deletes metadata. */
export async function eraseDerivedArtifactMetadata(
  database: AppDatabase,
  context: TenantContext,
  input: { artifactId: string; writeId: string; generation: number },
) {
  if (context.actorType !== 'service') throw new AppError('FORBIDDEN');
  await withTenantTx(database, context, async (tx) => {
    const [header] = await tx
      .select()
      .from(artifactLineage)
      .where(eq(artifactLineage.artifactId, checkedId(input.artifactId)))
      .for('update');
    if (
      !header ||
      header.writeId !== input.writeId ||
      header.generation !== input.generation ||
      header.state !== 'blocked'
    )
      throw new AppError('INVALID_STATE');
    await tx
      .update(artifactLineage)
      .set({ writeState: 'fenced', held: false })
      .where(eq(artifactLineage.artifactId, header.artifactId));
    await tx.execute(
      sql`select knowledge.erase_derived_artifact_metadata(${header.artifactId}::uuid,${header.writeId}::uuid,${header.generation}::bigint)`,
    );
  });
}

export function createDerivedArtifactPurge(deps: DerivedArtifactPurgeDeps): StructuredRecordPurge {
  const affected = (sourceId: string) =>
    sql`(not ${artifactLineage.inventoryComplete} or ${sourceId}::uuid in(select knowledge.artifact_required_sources(${artifactLineage.artifactId})))`;
  const confirm = async (tx: Tx, sourceId: string) => {
    const result = await tx.execute<{ remaining: number }>(
      sql`select knowledge.derived_artifacts_remaining(${checkedId(sourceId)}::uuid) as remaining`,
    );
    return { remaining: Number(result.rows[0]?.remaining ?? 1) };
  };
  const recordInput = (input: { kind: StructuredArtifactInput['kind']; id: string }) => {
    if (!['work_unit', 'project', 'client'].includes(input.kind))
      throw new AppError('INVALID_INPUT');
    return { kind: input.kind, id: checkedId(input.id) };
  };
  const recordAffected = (input: { kind: StructuredArtifactInput['kind']; id: string }) =>
    sql`((${artifactLineage.executionKind} in ('agent_run','system') and not ${artifactLineage.structuredInventoryComplete}) or exists(select 1 from knowledge.artifact_required_records(${artifactLineage.artifactId}) r where r.record_kind=${input.kind} and r.record_id=${input.id}::uuid))`;
  const confirmRecord = async (
    tx: Tx,
    input: { kind: StructuredArtifactInput['kind']; id: string },
  ) => {
    const result = await tx.execute<{ remaining: number }>(
      sql`select knowledge.derived_structured_artifacts_remaining(${input.kind},${input.id}::uuid) as remaining`,
    );
    return { remaining: Number(result.rows[0]?.remaining ?? 1) };
  };
  const purge = async (
    context: TenantContext,
    limit: number,
    selected: SQL,
    assertClosed: (tx: Tx) => Promise<void>,
    proofInTx: (tx: Tx) => Promise<{ remaining: number }>,
    reasonCode: 'KNOWLEDGE_SOURCE_PURGED' | 'STRUCTURED_INPUT_PURGED',
  ) => {
    if (context.actorType !== 'service') throw new AppError('FORBIDDEN');
    if (!Number.isSafeInteger(limit) || limit < 1 || limit > 100)
      throw new AppError('INVALID_INPUT');
    const headers = await withTenantTx(deps.database, context, async (tx) => {
      await assertClosed(tx);
      const rows = await tx
        .select()
        .from(artifactLineage)
        .where(and(selected, sql`${artifactLineage.physicalPurgedAt} is null`))
        .orderBy(asc(artifactLineage.held), asc(artifactLineage.artifactId))
        .limit(limit)
        .for('update');
      for (const row of rows) {
        await tx
          .update(artifactLineage)
          .set({ state: 'blocked' })
          .where(eq(artifactLineage.artifactId, row.artifactId));
        await markArtifactTombstone(tx, context, row, reasonCode);
      }
      return rows;
    });
    for (const header of headers) {
      if (!deps.lifecycle) continue;
      try {
        const result = await deps.lifecycle.erase(context, {
          artifactId: header.artifactId,
          workUnitId: header.workUnitId,
          objectKey: header.objectKey,
          artifactSha256: header.artifactSha256,
          writeId: header.writeId,
          generation: header.generation,
          writeState: header.writeState as 'active' | 'settled' | 'fenced' | 'unknown',
        });
        if (result.state === 'held') {
          await withTenantTx(deps.database, context, (tx) =>
            tx
              .update(artifactLineage)
              .set({ held: true })
              .where(eq(artifactLineage.artifactId, header.artifactId)),
          );
          continue;
        }
        if (
          result.state !== 'purged' ||
          !result.quiescent ||
          (await deps.store.exists(header.objectKey))
        )
          continue;
        await withTenantTx(deps.database, context, async (tx) => {
          const [current] = await tx
            .select()
            .from(artifactLineage)
            .where(eq(artifactLineage.artifactId, header.artifactId))
            .for('update');
          const [catalog] = await tx
            .select()
            .from(artifactAclCatalog)
            .where(eq(artifactAclCatalog.artifactId, header.artifactId));
          const [blob] = await tx
            .select()
            .from(blobLifecycle)
            .where(eq(blobLifecycle.artifactId, header.artifactId));
          if (
            !current ||
            current.writeId !== header.writeId ||
            current.generation !== header.generation ||
            catalog?.alive ||
            blob?.state !== 'purged' ||
            !['settled', 'fenced'].includes(current.writeState)
          )
            return;
          await tx
            .update(artifactLineage)
            .set({ physicalPurgedAt: new Date(), held: false })
            .where(eq(artifactLineage.artifactId, header.artifactId));
        });
      } catch {
        /* Retained header/token is a durable failed attempt, never a completed erasure. */
      }
    }
    return withTenantTx(deps.database, context, async (tx) => {
      const proof = await proofInTx(tx);
      const counts = await tx.execute<{ removed: number; held: number }>(sql`select
          count(*) filter(where ${artifactLineage.physicalPurgedAt} is not null)::integer as removed,
          count(*) filter(where ${artifactLineage.held} and ${artifactLineage.physicalPurgedAt} is null)::integer as held
          from ${artifactLineage} where ${selected}`);
      return {
        removed: Number(counts.rows[0]?.removed ?? 0),
        held: Number(counts.rows[0]?.held ?? 0),
        remaining: proof.remaining,
        confirmed: !!deps.lifecycle && proof.remaining === 0,
      };
    });
  };
  return {
    async confirmInTx(tx, context, input) {
      if (context.actorType !== 'service') throw new AppError('FORBIDDEN');
      return confirm(tx, input.sourceId);
    },
    async confirmRecordInTx(tx, context, input) {
      if (context.actorType !== 'service') throw new AppError('FORBIDDEN');
      return confirmRecord(tx, recordInput(input));
    },
    async purgeSource(context, input) {
      const sourceId = checkedId(input.sourceId);
      return purge(
        context,
        input.limit,
        affected(sourceId),
        async (tx) => {
          const [source] = await tx
            .select({ state: knowledgeSources.state })
            .from(knowledgeSources)
            .where(eq(knowledgeSources.id, sourceId));
          if (!source || source.state === 'active') throw new AppError('INVALID_STATE');
        },
        (tx) => confirm(tx, sourceId),
        'KNOWLEDGE_SOURCE_PURGED',
      );
    },
    async purgeRecord(context, input) {
      const record = recordInput(input);
      return purge(
        context,
        input.limit,
        recordAffected(record),
        async (tx) => {
          const [catalog] = await tx
            .select()
            .from(structuredRecordCatalog)
            .where(
              and(
                eq(structuredRecordCatalog.recordKind, record.kind),
                eq(structuredRecordCatalog.recordId, record.id),
              ),
            );
          const [closed] = await tx
            .select({ id: tombstones.targetId })
            .from(tombstones)
            .where(and(eq(tombstones.targetType, record.kind), eq(tombstones.targetId, record.id)));
          if (!catalog || (catalog.alive && !closed)) throw new AppError('INVALID_STATE');
        },
        (tx) => confirmRecord(tx, record),
        'STRUCTURED_INPUT_PURGED',
      );
    },
  };
}
